package com.yeyamo_mobile.api.partner_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import com.yeyamo_mobile.api.partner_service.domain.model.DocumentType;import jakarta.persistence.*;
@Entity @Table(name="partner_documents") public class PartnerDocumentEntity { @Id private UUID id;@Column(name="partner_id",nullable=false)private UUID partnerId;@Enumerated(EnumType.STRING)@Column(name="document_type",nullable=false)private DocumentType documentType;@Column(name="storage_key",nullable=false,unique=true,length=500)private String storageKey;@Column(name="original_filename",nullable=false)private String originalFilename;@Column(name="content_type",nullable=false)private String contentType;@Column(name="size_bytes",nullable=false)private long sizeBytes;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getPartnerId(){return partnerId;}public void setPartnerId(UUID v){partnerId=v;}public DocumentType getDocumentType(){return documentType;}public void setDocumentType(DocumentType v){documentType=v;}public String getStorageKey(){return storageKey;}public void setStorageKey(String v){storageKey=v;}public String getOriginalFilename(){return originalFilename;}public void setOriginalFilename(String v){originalFilename=v;}public String getContentType(){return contentType;}public void setContentType(String v){contentType=v;}public long getSizeBytes(){return sizeBytes;}public void setSizeBytes(long v){sizeBytes=v;}public Instant getUploadedAt(){return uploadedAt;}public void setUploadedAt(Instant v){uploadedAt=v;} }
